import { MainWrapper, ContentWrapper, ProjectModule } from "./index.stitches";
import data from "../../data/project.json";

console.log(data);

function ProjectGrid() {
  return (
    <MainWrapper>
      <ContentWrapper>
        {data.map((item, i) => {
          return (
            <ProjectModule key={i}>
                <Image></Image>
              <p>{item[0]}</p>
              <p>{item[2]}</p>
            </ProjectModule>
          );
        })}
      </ContentWrapper>
    </MainWrapper>
  );
}

export default ProjectGrid;
